# ------------------------------------------------------------------
# ペイロード
# ------------------------------------------------------------------

def _payload_tar():
    raw = base64.b64decode(PAYLOAD)
    return tarfile.open(fileobj=io.BytesIO(gzip.decompress(raw)), mode='r')


def _members():
    tf = _payload_tar()
    out = []
    for m in tf.getmembers():
        if m.isfile() and m.name.startswith(PREFIX):
            out.append((m.name[len(PREFIX):], m.size, tf.extractfile(m).read()))
    tf.close()
    out.sort()
    return out


def _read_one(rel):
    for name, size, data in _members():
        if name == rel:
            return data
    return None


# ------------------------------------------------------------------
# --list
# ------------------------------------------------------------------

def cmd_list():
    items = _members()
    total = sum(s for _, s, _ in items)
    print(f'FUJIN-P 種パッケージ（{BUILD_INFO}）')
    print(f'{len(items)} ファイル・合計 {total:,} バイト\n')
    for name, size, _ in items:
        print(f'  {size:>8,}  {name}')
    print('\nconfig.py は入っていない．config_template.py を写して書く．')


# ------------------------------------------------------------------
# --files
# ------------------------------------------------------------------

def cmd_files(dest, force):
    dest = os.path.abspath(os.path.expanduser(dest))
    items = _members()
    stamp = time.strftime('%Y%m%d_%H%M%S')
    backup = os.path.join(dest, f'fujinp_seed_backup_{stamp}')

    written, skipped, backed = [], [], []

    for name, size, data in items:
        path = os.path.join(dest, name)
        if os.path.exists(path):
            if not force:
                skipped.append(name)
                continue
            bpath = os.path.join(backup, name)
            os.makedirs(os.path.dirname(bpath), exist_ok=True)
            with open(path, 'rb') as f_old, open(bpath, 'wb') as f_bak:
                f_bak.write(f_old.read())
            backed.append(name)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        written.append(name)

    print(f'展開先: {dest}')
    print(f'書いたファイル: {len(written)}')
    if backed:
        print(f'上書き前に退避: {len(backed)} → {backup}')
    if skipped:
        print(f'既にあるので触らなかったファイル: {len(skipped)}')
        for n in skipped[:20]:
            print(f'    {n}')
        if len(skipped) > 20:
            print(f'    …ほか {len(skipped) - 20} 件')
        print('  上書きするなら --files --force を付けて実行する．')

    print()
    print('次にやること')
    print('  1. データベースを作る（PythonAnywhere の Databases タブ）')
    print('       <アカウント>$default ← 必須')
    print('       <アカウント>$fujinp・<アカウント>$public ← アプリを入れるとき')
    print('  2. 依存ライブラリを入れる')
    print('       pip3 install --user -r requirements.txt')
    print('  3. config.py を書く')
    print('       cp config_template.py config.py  として中の <...> を埋める')
    print('  4. テーブルを作る')
    print('       python3 fujinp_kernel_install.py --schema')
    print()
    print('  詳しくは fujinp_seed/README_install.md を読む．')


