def _split_sql(text):
    """; で文を切る．引用符・バッククォート・行コメントの中の ; は無視する．"""
    stmts, buf = [], []
    quote = None
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if quote:
            buf.append(c)
            if c == '\\' and quote in ("'", '"') and i + 1 < n:
                buf.append(text[i + 1])
                i += 2
                continue
            if c == quote:
                quote = None
            i += 1
            continue
        if c == '-' and text[i:i + 2] == '--':
            j = text.find('\n', i)
            j = n if j < 0 else j + 1
            buf.append(text[i:j])
            i = j
            continue
        if c in ("'", '"', '`'):
            quote = c
            buf.append(c)
            i += 1
            continue
        if c == ';':
            s = ''.join(buf).strip()
            if s:
                stmts.append(s)
            buf = []
            i += 1
            continue
        buf.append(c)
        i += 1
    s = ''.join(buf).strip()
    if s:
        stmts.append(s)
    return [s for s in stmts if not all(l.strip().startswith('--') or not l.strip()
                                        for l in s.splitlines())]


def cmd_schema(dest):
    dest = os.path.abspath(os.path.expanduser(dest))
    if dest not in sys.path:
        sys.path.insert(0, dest)

    if not os.path.exists(os.path.join(dest, 'config.py')):
        sys.exit(f'{dest}/config.py がありません．config_template.py を写して書いてから実行してください．')

    try:
        import mysql.connector
    except ImportError:
        sys.exit('mysql-connector-python が入っていません．\n'
                 '  pip3 install --user -r requirements.txt  を先に実行してください．')

    try:
        from config import Config
        from db import DatabaseConfig
    except Exception as e:
        sys.exit(f'config.py / db.py を読めませんでした: {e}')

    dbname = Config.DB_DEFAULT
    print(f'接続先: {dbname}')
    try:
        conn = mysql.connector.connect(**DatabaseConfig.default())
    except Exception as e:
        sys.exit(f'接続できません: {e}\n'
                 'config.py の DB_HOST / DB_USER / DB_PASSWORD / DB_ACCOUNT と，\n'
                 'データベース（<アカウント>$default）が作ってあるかを確かめてください．')

    cur = conn.cursor()
    cur.execute('SHOW TABLES')
    before = {r[0] for r in cur.fetchall()}

    sql = _read_one('fujinp_seed/seed_schema.sql')
    if sql is None:
        sys.exit('パッケージに seed_schema.sql がありません（壊れています）．')
    stmts = _split_sql(sql.decode('utf-8'))

    ok, fail = 0, []
    for s in stmts:
        try:
            cur.execute(s)
            ok += 1
        except Exception as e:
            head = ' '.join(s.split())[:70]
            fail.append((head, str(e)))
    conn.commit()

    cur.execute('SHOW TABLES')
    after = {r[0] for r in cur.fetchall()}
    created = sorted(after - before)

    print(f'実行した文: {ok} / {len(stmts)}')
    print(f'新しく作られたテーブル: {len(created)}')
    for t in created:
        print(f'    {t}')
    if before & after:
        print(f'既にあったテーブル: {len(before & after)}（触っていません）')
    if fail:
        print(f'\n失敗した文: {len(fail)}')
        for head, err in fail:
            print(f'    {head} …\n      {err}')

    cur.close()

    # 正本（app_registry.json）を書き出す
    try:
        from fujinp import registry as _reg
        dcur = conn.cursor(dictionary=True)
        data = _reg.publish(dcur)
        conn.commit()
        dcur.close()
        n_apps = len(data.get('apps') or [])
        n_sec = len(data.get('sections') or [])
        print(f'\n正本を書き出しました: {_reg.REGISTRY_FILE}')
        print(f'    アプリ {n_apps} 件・区画 {n_sec} 件')
    except Exception as e:
        print(f'\n正本の書き出しに失敗しました: {e}')
        print('    fujinp/registry.py が置かれているか，DB に kernel の3行が入ったかを確かめてください．')

    conn.close()

    print()
    print('次にやること')
    print('  5. WSGI ファイルを設定して Reload する（Web タブ）')
    print('  6. 最初の admin を登録する')
    print('       python3 fujinp_seed/make_admin.py')
    print('       表示された INSERT 文を MySQL コンソールで実行する')
    print('  7. ブラウザでサイトを開き，そのメールアドレスとパスワードでログインする')
    print('       admin ダッシュボードにアプシャのカードが出れば，種は立ち上がっています．')


# ------------------------------------------------------------------

USAGE = """FUJIN-P 種の導入スクリプト

  python3 fujinp_kernel_install.py --list              中身を見る（何も書かない）
  python3 fujinp_kernel_install.py --files [--force]   ファイルを展開する
  python3 fujinp_kernel_install.py --schema            テーブルを作り，正本を発行する

  --dest DIR   展開先（既定はホームディレクトリ）
  --force      既にあるファイルも上書きする（上書き前に退避する）
"""


def main(argv):
    args = list(argv[1:])
    if not args or '-h' in args or '--help' in args:
        print(USAGE)
        return 0

    dest = os.path.expanduser('~')
    if '--dest' in args:
        i = args.index('--dest')
        try:
            dest = args[i + 1]
        except IndexError:
            sys.exit('--dest のあとにディレクトリを書いてください．')
        del args[i:i + 2]
    force = '--force' in args
    if force:
        args.remove('--force')

    if args[0] == '--list':
        cmd_list()
    elif args[0] == '--files':
        cmd_files(dest, force)
    elif args[0] == '--schema':
        cmd_schema(dest)
    else:
        print(USAGE)
        return 1
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))
